// The extra generated file of a module that embeds the project's theme asset (issue #81, ADR-048):
// the serializer output as an `inline constexpr` byte array plus the `EmbeddedTheme` record startup
// consumes (docs/specs/compiled-stylesheet-v1.md "Theme asset blob").

#include "codegen_internal.hpp"

#include <cstddef>
#include <cstdint>
#include <string>
#include <string_view>

namespace tessera::compiler::codegen::internal {
namespace {

constexpr std::size_t kBytesPerLine = 12;
constexpr char kHexDigits[] = "0123456789abcdef";

std::string byte_text(std::uint8_t value) {
    std::string text("0x");
    text += kHexDigits[(value >> 4U) & 0xFU];
    text += kHexDigits[value & 0xFU];
    return text;
}

} // namespace

std::string emit_theme_header(std::string_view module_name, std::span<const std::uint8_t> bytes) {
    CppWriter writer;
    writer.line("// Generated by tessera_codegen. Do not edit.");
    writer.line("// Embedded theme asset blob (docs/specs/compiled-stylesheet-v1.md): load with");
    writer.line("// tessera::ui::style::load_theme_asset_blob at startup.");
    writer.line("#pragma once");
    writer.line("#include <array>");
    writer.line("#include <cstdint>");
    writer.line("#include <span>");
    writer.line("#include \"tessera/ui/style/theme_asset.hpp\"");
    writer.open("namespace " + std::string(module_name));

    writer.line("inline constexpr std::array<std::uint8_t, " + std::to_string(bytes.size()) +
                "> kThemeBlob = {");
    ++writer.indent;
    std::string line_text;
    for (std::size_t byte = 0; byte < bytes.size(); ++byte) {
        line_text += byte_text(bytes[byte]);
        line_text += ", ";
        if ((byte + 1) % kBytesPerLine == 0) {
            line_text.pop_back(); // the line keeps its trailing comma, not the space
            writer.line(line_text);
            line_text.clear();
        }
    }
    if (!line_text.empty()) {
        line_text.pop_back();
        writer.line(line_text);
    }
    --writer.indent;
    writer.line("};");
    writer.line("inline constexpr tessera::ui::style::EmbeddedTheme kEmbeddedTheme = "
                "{std::span<const std::uint8_t>(kThemeBlob)};");
    writer.close(" // namespace " + std::string(module_name));
    return writer.text;
}

} // namespace tessera::compiler::codegen::internal
